<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import http from '@/api/http';import { useAuthStore } from '@/stores/auth';import { ElMessage } from 'element-plus';import type { Dict } from '@/types'
const auth=useAuthStore(),rows=ref<Dict[]>([]),materials=ref<Dict[]>([]),suppliers=ref<Dict[]>([]),dialog=ref(false),convertDialog=ref(false),selected=ref<Dict>(),form=reactive<Dict>({requiredDate:'',purpose:'',items:[{materialId:'',quantity:1,estimatedUnitPrice:0,remark:''}]}),convert=reactive<Dict>({supplierId:'',deliveryDate:'',taxRate:.13,terms:'按合同约定交货',priceOverrides:{}})
async function load(){[rows.value,materials.value,suppliers.value]=await Promise.all([http.get('/requisitions'),http.get('/materials'),http.get('/suppliers')])}function add(){form.items.push({materialId:'',quantity:1,estimatedUnitPrice:0,remark:''})}async function save(){await http.post('/requisitions',form);ElMessage.success('采购申请已保存');dialog.value=false;load()}async function submit(row:Dict){await http.post(`/requisitions/${row.id}/submit`);ElMessage.success('已进入审批流程');load()}function openConvert(row:Dict){selected.value=row;convertDialog.value=true}async function doConvert(){await http.post(`/requisitions/${selected.value?.id}/convert`,convert);ElMessage.success('采购订单已生成');convertDialog.value=false;load()}onMounted(load)
const name:Dict={DRAFT:'草稿',PENDING_APPROVAL:'审批中',APPROVED:'已批准',REJECTED:'已驳回',CONVERTED:'已转订单',CANCELLED:'已取消'};const type:Dict={DRAFT:'info',PENDING_APPROVAL:'warning',APPROVED:'success',REJECTED:'danger',CONVERTED:'success'}
</script>
<template><div class="page"><div class="page-head"><div><h1>采购申请</h1><p>按金额自动匹配审批链，驳回后可修改并重新提交</p></div><el-button v-if="auth.can('requisition:create')" type="primary" @click="dialog=true">新建申请</el-button></div><div class="panel panel-pad"><el-table :data="rows"><el-table-column prop="requisitionNo" label="申请单号" width="170"/><el-table-column prop="department" label="部门"/><el-table-column prop="applicant" label="申请人"/><el-table-column prop="purpose" label="用途" min-width="220"/><el-table-column prop="requiredDate" label="需求日期"/><el-table-column prop="budgetAmount" label="预算金额"><template #default="s">¥ {{Number(s.row.budgetAmount).toLocaleString()}}</template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="type[s.row.status]">{{name[s.row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="190"><template #default="s"><el-button v-if="['DRAFT','REJECTED'].includes(s.row.status)&&auth.can('requisition:submit')" link type="primary" @click="submit(s.row)">提交</el-button><el-button v-if="s.row.status==='APPROVED'&&auth.can('purchaseorder:edit')" link type="success" @click="openConvert(s.row)">转订单</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" title="新建采购申请" width="860px"><el-form :model="form" label-width="90px"><el-form-item label="需求日期"><el-date-picker v-model="form.requiredDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="采购用途"><el-input v-model="form.purpose" type="textarea"/></el-form-item><el-table :data="form.items"><el-table-column label="物资" min-width="220"><template #default="s"><el-select v-model="s.row.materialId" filterable style="width:100%"><el-option v-for="m in materials" :key="m.id" :label="`${m.code} ${m.name}`" :value="m.id"/></el-select></template></el-table-column><el-table-column label="数量" width="130"><template #default="s"><el-input-number v-model="s.row.quantity" :min="1"/></template></el-table-column><el-table-column label="预估单价" width="160"><template #default="s"><el-input-number v-model="s.row.estimatedUnitPrice" :min="0" :precision="2"/></template></el-table-column><el-table-column label="备注"><template #default="s"><el-input v-model="s.row.remark"/></template></el-table-column><el-table-column width="60"><template #default="s"><el-button link type="danger" @click="form.items.splice(s.$index,1)">删</el-button></template></el-table-column></el-table><el-button text type="primary" @click="add">+ 添加明细</el-button></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存草稿</el-button></template></el-dialog><el-dialog v-model="convertDialog" title="生成采购订单" width="520px"><el-form :model="convert" label-width="100px"><el-form-item label="供应商"><el-select v-model="convert.supplierId" style="width:100%"><el-option v-for="s in suppliers.filter(x=>x.status==='QUALIFIED')" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="交付日期"><el-date-picker v-model="convert.deliveryDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="税率"><el-input-number v-model="convert.taxRate" :step=".01" :max="1"/></el-form-item><el-form-item label="商业条款"><el-input v-model="convert.terms" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="convertDialog=false">取消</el-button><el-button type="primary" @click="doConvert">生成订单</el-button></template></el-dialog></div></template>
